#!/bin/bash
# Verify that the two routes to the A51 board layer agree on a real xnu tree:
#   route A: patches 0001..0124, then tools/a51/apply-a51.py --skip-stage1
#   route B: patches 0001..0125 (0125 generated by tools/a51/mkpatch0125.py)
# Both must produce byte-identical A5XELTE.h and bsd/dev/sweet_ufs.c.
set -uo pipefail
REPO=/mnt/g/a51-port/ios-a51
PY=python3

mkdir -p /tmp/p124
rm -f /tmp/p124/*.patch /tmp/p124/*.sh
for f in "$REPO"/xnu/patches/*; do
    b=${f##*/}
    case "$b" in
        0125-*) continue ;;
    esac
    cp "$f" /tmp/p124/
done
echo "patches for route A: $(ls /tmp/p124 | wc -l)"

tr -d '\r' < "$REPO/tools/dreamlte/prep-xnu-tree.sh" > /tmp/prep.sh
bash /tmp/prep.sh /tmp/p124 /home/nickolay/xnuwork124 2>&1 | tail -2

A=/home/nickolay/xnuwork124/xnu
B=/home/nickolay/xnuwork/xnu

echo "== route A: apply-a51.py --skip-stage1 =="
$PY "$REPO/tools/a51/apply-a51.py" "$A" --skip-stage1 | tail -3

echo
echo "== diff route A vs route B =="
rc=0
for rel in pexpert/pexpert/arm64/A5XELTE.h bsd/dev/sweet_ufs.c; do
    if diff -u "$B/$rel" "$A/$rel" > /tmp/d.txt 2>&1; then
        echo "IDENTICAL  $rel"
    else
        echo "DIFFERS    $rel"
        head -40 /tmp/d.txt
        rc=1
    fi
done

echo
echo "== whole-tree diff (should list nothing but the two files, if any) =="
diff -rq --exclude=.git "$B" "$A" 2>&1 | head -20

exit $rc
